def claro(fondo_rgba):
    return f"linear-gradient(180deg,rgba(255,255,255,0) 48%,{fondo_rgba} 78%,{fondo_rgba} 100%)"


def oscuro(rgba):
    return f"linear-gradient(180deg,rgba(0,0,0,0) 40%,{rgba} 75%,{rgba} 100%)"


